<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WastedToken Mint — Die-Struck Challenge Coins</title>
<style>
  :root{
    --bg:#08080c;
    --panel:#101017;
    --panel-2:#14141c;
    --line:#232330;
    --gold:#d8b25a;
    --gold-bright:#f0d48a;
    --text:#eae5d9;
    --muted:#9b948a;
    --serif:Georgia,'Times New Roman',serif;
    --sans:'Segoe UI',system-ui,-apple-system,Helvetica,Arial,sans-serif;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    background:var(--bg);
    color:var(--text);
    font-family:var(--sans);
    line-height:1.6;
    overflow-x:hidden;
  }
  ::selection{background:var(--gold);color:#141005}

  /* ---------- header ---------- */
  header{
    position:sticky;top:0;z-index:50;
    display:flex;align-items:center;justify-content:space-between;
    padding:16px clamp(20px,5vw,64px);
    background:rgba(8,8,12,.82);
    backdrop-filter:blur(10px);
    border-bottom:1px solid var(--line);
  }
  .logo{
    font-family:var(--serif);
    font-size:17px;letter-spacing:.22em;
    color:var(--gold);text-decoration:none;white-space:nowrap;
  }
  .logo b{color:var(--text);font-weight:400}
  nav{display:flex;gap:clamp(14px,3vw,36px);align-items:center}
  nav a{
    color:var(--muted);text-decoration:none;font-size:12px;
    letter-spacing:.18em;text-transform:uppercase;transition:color .2s;
  }
  nav a:hover{color:var(--gold-bright)}
  #cart{
    border:1px solid var(--line);border-radius:999px;padding:6px 14px;
    color:var(--text);font-size:12px;letter-spacing:.1em;
  }

  /* ---------- hero ---------- */
  .hero{
    position:relative;
    display:flex;flex-direction:column;align-items:center;text-align:center;
    padding:clamp(36px,6vh,72px) 20px 80px;
    background:
      radial-gradient(ellipse 70% 45% at 50% 30%, rgba(216,178,90,.07), transparent 70%),
      var(--bg);
  }
  .eyebrow{
    font-size:11px;letter-spacing:.34em;text-transform:uppercase;
    color:var(--gold);margin-bottom:18px;
  }
  .hero h1{
    font-family:var(--serif);font-weight:400;
    font-size:clamp(34px,5.4vw,64px);
    line-height:1.12;max-width:15ch;margin-bottom:18px;
  }
  .hero h1 em{color:var(--gold-bright);font-style:italic}
  .hero .sub{
    max-width:56ch;color:var(--muted);font-size:clamp(15px,1.6vw,17px);
    margin-bottom:36px;
  }
  #coin-hero{
    width:min(78vw,540px);height:min(78vw,540px);
    border-radius:22px;
    border:1px solid var(--line);
    box-shadow:0 40px 90px -30px rgba(0,0,0,.9), 0 0 120px -40px rgba(216,178,90,.35);
    display:block;
    margin-bottom:40px;
  }
  .cta-row{display:flex;gap:16px;flex-wrap:wrap;justify-content:center}
  .btn{
    display:inline-block;padding:13px 30px;border-radius:4px;
    font-size:12px;letter-spacing:.22em;text-transform:uppercase;
    text-decoration:none;cursor:pointer;transition:all .2s;
    font-family:var(--sans);
  }
  .btn-gold{
    background:linear-gradient(180deg,var(--gold-bright),var(--gold));
    color:#191204;border:1px solid var(--gold-bright);font-weight:600;
  }
  .btn-gold:hover{filter:brightness(1.1);transform:translateY(-1px)}
  .btn-ghost{border:1px solid var(--line);color:var(--text);background:transparent}
  .btn-ghost:hover{border-color:var(--gold);color:var(--gold-bright)}

  /* ---------- sections ---------- */
  section{padding:clamp(60px,9vh,110px) clamp(20px,6vw,80px);border-top:1px solid var(--line)}
  .kicker{font-size:11px;letter-spacing:.34em;text-transform:uppercase;color:var(--gold);margin-bottom:14px}
  h2{font-family:var(--serif);font-weight:400;font-size:clamp(26px,3.4vw,40px);margin-bottom:22px}

  .about-grid{
    display:grid;grid-template-columns:1.4fr 1fr;gap:clamp(28px,5vw,72px);
    max-width:1120px;margin:0 auto;align-items:start;
  }
  .about-grid p{color:var(--muted);margin-bottom:16px;font-size:15.5px}
  .about-grid p strong{color:var(--text);font-weight:600}
  .stats{display:grid;gap:14px}
  .stat{
    background:var(--panel);border:1px solid var(--line);border-radius:10px;
    padding:18px 22px;
  }
  .stat .n{font-family:var(--serif);font-size:26px;color:var(--gold-bright)}
  .stat .l{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
  @media (max-width:820px){.about-grid{grid-template-columns:1fr}}

  /* ---------- collection ---------- */
  #collection .lede{color:var(--muted);max-width:60ch;margin-bottom:44px}
  .grid{
    display:grid;gap:22px;max-width:1240px;margin:0 auto;
    grid-template-columns:repeat(auto-fit,minmax(250px,1fr));
  }
  .edition{
    position:relative;
    background:linear-gradient(180deg,var(--panel-2),var(--panel));
    border:1px solid var(--line);border-radius:14px;
    padding:20px 20px 24px;display:flex;flex-direction:column;gap:6px;
    transition:transform .25s, border-color .25s, box-shadow .25s;
    overflow:hidden;
  }
  .edition:hover{transform:translateY(-5px);border-color:#3a3a4c;box-shadow:0 24px 50px -24px rgba(0,0,0,.85)}
  .edition-canvas{width:100%;height:auto;border-radius:10px;display:block;margin-bottom:10px}
  .edition h3{font-family:var(--serif);font-weight:400;font-size:21px;letter-spacing:.02em}
  .edition .denom{font-size:12px;letter-spacing:.18em;color:var(--gold);text-transform:uppercase}
  .edition .blurb{font-size:13.5px;color:var(--muted);flex:1;margin:6px 0 14px}
  button.buy{
    appearance:none;width:100%;padding:12px 0;border-radius:4px;cursor:pointer;
    background:transparent;border:1px solid var(--gold);color:var(--gold-bright);
    font-size:12px;letter-spacing:.22em;text-transform:uppercase;font-family:var(--sans);
    transition:all .2s;
  }
  button.buy:hover{background:var(--gold);color:#191204;font-weight:600}
  .flag{
    width:100%;text-align:center;padding:12px 0;border-radius:4px;
    font-size:12px;letter-spacing:.22em;text-transform:uppercase;
    border:1px dashed var(--line);color:var(--muted);
  }
  .ribbon{
    position:absolute;top:22px;right:-44px;transform:rotate(38deg);
    padding:6px 52px;font-size:11px;letter-spacing:.3em;font-weight:700;
    z-index:2;pointer-events:none;
  }
  .edition[data-state="sold-out"] .ribbon{background:#7a1f1f;color:#ffd9d9}
  .edition[data-state="sold-out"] .edition-canvas{opacity:.55;filter:saturate(.65)}
  .edition[data-state="coming-soon"] .ribbon{background:#25253a;color:#c9c9ee}
  .edition[data-state="coming-soon"] .edition-canvas{opacity:.85}

  /* ---------- footer ---------- */
  footer{
    border-top:1px solid var(--line);
    padding:44px clamp(20px,6vw,80px);
    display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center;
    color:var(--muted);font-size:13px;
  }
  footer .fl{font-family:var(--serif);letter-spacing:.2em;color:var(--gold)}

  .reveal{opacity:0;transform:translateY(22px);transition:opacity .7s ease,transform .7s ease}
  .reveal.in{opacity:1;transform:none}
</style>
</head>
