<script>
(function(){
'use strict';

/* ============ vector helpers ============ */
function dot(a,b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}
function nrm(a){var l=Math.hypot(a[0],a[1],a[2])||1;return [a[0]/l,a[1]/l,a[2]/l];}
function px(c,m,s){
  s=s||0;
  var r=Math.min(255,Math.round(c[0]*m+255*s)),
      g=Math.min(255,Math.round(c[1]*m+255*s)),
      b=Math.min(255,Math.round(c[2]*m+255*s));
  return 'rgb('+Math.max(0,r)+','+Math.max(0,g)+','+Math.max(0,b)+')';
}

/* ============ emboss: dark away from light, bright toward it ============ */
function emboss(ctx,e,draw){
  ctx.save(); ctx.translate(-e.dx,-e.dy); ctx.fillStyle=e.dark;  ctx.strokeStyle=e.dark;  draw(ctx); ctx.restore();
  ctx.save(); ctx.translate( e.dx, e.dy); ctx.fillStyle=e.light; ctx.strokeStyle=e.light; draw(ctx); ctx.restore();
  ctx.save();                             ctx.fillStyle=e.main;  ctx.strokeStyle=e.main;  draw(ctx); ctx.restore();
}

/* curved text; local coords are y-down like normal canvas */
function arcText(ctx,text,r,bottom){
  var n=text.length, step=0.128, span=step*n;
  for(var i=0;i<n;i++){
    var a = bottom
      ? Math.PI/2 + span/2 - step*(i+0.5)
      : -Math.PI/2 - span/2 + step*(i+0.5);
    ctx.save();
    ctx.translate(r*Math.cos(a), r*Math.sin(a));
    ctx.rotate(bottom ? a-Math.PI/2 : a+Math.PI/2);
    ctx.fillText(text[i],0,0);
    ctx.restore();
  }
}

function beadsAndRings(ctx,e){
  emboss(ctx,e,function(c){          // rim lip
    c.beginPath(); c.arc(0,0,95,0,7); c.lineWidth=4; c.stroke();
  });
  emboss(ctx,e,function(c){          // bead circle
    c.beginPath();
    for(var i=0;i<56;i++){
      var a=i/56*Math.PI*2, X=86*Math.cos(a), Y=86*Math.sin(a);
      c.moveTo(X+2.4,Y); c.arc(X,Y,2.4,0,7);
    }
    c.fill();
  });
  emboss(ctx,e,function(c){ c.beginPath(); c.arc(0,0,78,0,7); c.lineWidth=1.6; c.stroke(); });
  emboss(ctx,e,function(c){ c.beginPath(); c.arc(0,0,60,0,7); c.lineWidth=1.2; c.stroke(); });
}

function drawFrontDesign(ctx,e,label){
  beadsAndRings(ctx,e);
  ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.font='600 11px Georgia, "Times New Roman", serif';
  emboss(ctx,e,function(c){ arcText(c,'\u2726 WASTEDTOKEN MINT \u2726',69,false); });
  emboss(ctx,e,function(c){ arcText(c,label||'HEAVY IN HAND \u00B7 MMXXVI',69,true); });

  // sunburst behind monogram
  ctx.save();
  ctx.strokeStyle='rgba(0,0,0,0.20)'; ctx.lineWidth=1;
  ctx.beginPath();
  for(var i=0;i<24;i++){
    var a=i/24*Math.PI*2, r1=27, r2=(i%2?44:53);
    ctx.moveTo(r1*Math.cos(a),r1*Math.sin(a));
    ctx.lineTo(r2*Math.cos(a),r2*Math.sin(a));
  }
  ctx.stroke();
  ctx.restore();

  ctx.font='900 62px Georgia, "Times New Roman", serif';
  emboss(ctx,e,function(c){ c.fillText('W',0,2); });
  ctx.font='700 10px Georgia, "Times New Roman", serif';
  emboss(ctx,e,function(c){ c.fillText('\u2726  MINT  \u2726',0,42); });
}

function drawBackDesign(ctx,e,denom){
  beadsAndRings(ctx,e);
  ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.font='600 11px Georgia, "Times New Roman", serif';
  emboss(ctx,e,function(c){ arcText(c,'WASTEDTOKEN MINT',69,false); });
  emboss(ctx,e,function(c){ arcText(c,'NO CASH VALUE \u00B7 ALL GLORY',69,true); });

  // laurel leaves, both branches
  emboss(ctx,e,function(c){
    c.beginPath();
    var k,i,a,X,Y,rot;
    for(k=0;k<2;k++){
      for(i=0;i<7;i++){
        a = k===0 ? Math.PI*0.60+i*0.11 : Math.PI*0.40-i*0.11;
        X=49*Math.cos(a); Y=49*Math.sin(a);
        rot = a + Math.PI/2 + (k===0?-0.35:0.35);
        c.moveTo(X,Y);
        c.ellipse(X,Y,7,2.6,rot,0,Math.PI*2);
      }
    }
    c.fill();
  });

  ctx.font='700 14px Georgia, "Times New Roman", serif';
  emboss(ctx,e,function(c){ c.fillText('\u2726',0,-38); });
  ctx.font='900 27px Georgia, "Times New Roman", serif';
  emboss(ctx,e,function(c){ c.fillText(denom||'10,000',0,-10); });
  ctx.font='700 12px Georgia, "Times New Roman", serif';
  emboss(ctx,e,function(c){ c.fillText('T O K E N S',0,18); });
}

/* ============ full coin render — pure function of (t, options) ============ */
function drawCoin(ctx,size,t,pal,opts){
  opts=opts||{};
  var W=size, cx=W/2, cy0=W/2, S=W*0.40;
  var h=0.115, DR=100;
  var yaw   = (opts.yaw  !==undefined)?opts.yaw  : Math.PI*2*t;
  var pitch = (opts.pitch!==undefined)?opts.pitch: 0.85*Math.sin(Math.PI*2*t);

  var cyw=Math.cos(yaw), sy=Math.sin(yaw), cp=Math.cos(pitch), sp=Math.sin(pitch);
  // basis after Rx(pitch)*Ry(yaw)
  var u=[cyw, sy*sp, -sy*cp];
  var v=[0,   cp,     sp   ];
  var w=[sy, -cyw*sp, cyw*cp];

  var L=nrm([0.5,0.62,0.6]);
  var Hv=nrm([L[0],L[1],L[2]+1]);
  var c=pal;

  ctx.setTransform(1,0,0,1,0,0);
  var bg=ctx.createRadialGradient(cx,cy0*0.88,W*0.04,cx,cy0,W*0.72);
  bg.addColorStop(0,'#1b1b23'); bg.addColorStop(1,'#0a0a0e');
  ctx.fillStyle=bg; ctx.fillRect(0,0,W,W);

  /* ---- reeded edge (cylinder side) ---- */
  var SEG=440, NR=96, i;
  for(i=0;i<SEG;i++){
    var a0=i/SEG*Math.PI*2, a1=(i+1.35)/SEG*Math.PI*2, am=(a0+a1)/2;
    var ca=Math.cos(am), sa=Math.sin(am);
    var nm=[ca*u[0]+sa*v[0], ca*u[1]+sa*v[1], ca*u[2]+sa*v[2]];
    if(nm[2] <= -0.004) continue;
    var c0=Math.cos(a0), s0=Math.sin(a0), c1=Math.cos(a1), s1=Math.sin(a1);
    var n0=[c0*u[0]+s0*v[0], c0*u[1]+s0*v[1]];
    var n1=[c1*u[0]+s1*v[0], c1*u[1]+s1*v[1]];
    var d=Math.max(0,dot(nm,L));
    var spc=Math.pow(Math.max(0,dot(nm,Hv)),36);
    var reed=0.55+0.45*(0.5+0.5*Math.cos(am*NR));
    var col=px(c, 0.28+0.92*d*reed, spc*reed*0.85);
    ctx.fillStyle=col; ctx.strokeStyle=col; ctx.lineWidth=0.8;
    ctx.beginPath();
    ctx.moveTo(cx+S*(n0[0]+h*w[0]), cy0-S*(n0[1]+h*w[1]));
    ctx.lineTo(cx+S*(n1[0]+h*w[0]), cy0-S*(n1[1]+h*w[1]));
    ctx.lineTo(cx+S*(n1[0]-h*w[0]), cy0-S*(n1[1]-h*w[1]));
    ctx.lineTo(cx+S*(n0[0]-h*w[0]), cy0-S*(n0[1]-h*w[1]));
    ctx.closePath(); ctx.fill(); ctx.stroke();
  }

  /* ---- visible face ---- */
  if(Math.abs(w[2])>0.015){
    var front = w[2]>=0, sgn=front?1:-1;
    var ex = front ? u : [-u[0],-u[1],-u[2]];
    var ey = [-v[0],-v[1],-v[2]];                 // local +y is screen-down
    var C3=[sgn*h*w[0], sgn*h*w[1], sgn*h*w[2]];
    var nF=[sgn*w[0], sgn*w[1], sgn*w[2]];
    var k=S/DR;

    var lx=dot(L,ex), ly=dot(L,ey);
    var ll=Math.hypot(lx,ly);
    var gx= ll>1e-4?lx/ll:0.7, gy= ll>1e-4?ly/ll:-0.7;
    var faceDiff=Math.max(0,dot(nF,L));
    var faceSpec=Math.pow(Math.max(0,dot(nF,Hv)),22);

    ctx.save();
    ctx.setTransform(k*ex[0], -k*ex[1], k*ey[0], -k*ey[1], cx+S*C3[0], cy0-S*C3[1]);
    ctx.beginPath(); ctx.arc(0,0,DR+0.4,0,7); ctx.clip();

    // metallic base with a moving hotspot (tracks the light in face-space)
    var g=ctx.createRadialGradient(lx*55,ly*55,8, lx*18,ly*18,175);
    g.addColorStop(0,   px(c, 1.00+0.55*faceDiff, 0.06));
    g.addColorStop(0.5, px(c, 0.62+0.50*faceDiff));
    g.addColorStop(1,   px(c, 0.38+0.30*faceDiff));
    ctx.fillStyle=g; ctx.fillRect(-DR-2,-DR-2,2*DR+4,2*DR+4);

    // relief work
    var eC={ dx:gx*1.5, dy:gy*1.5,
             dark: px(c,0.30),
             light:px(c,1.28,0.30),
             main: px(c,1.16,0.05) };
    if(front) drawFrontDesign(ctx,eC,opts.label);
    else      drawBackDesign(ctx,eC,opts.denom);

    // ambient shading when face turns from the light
    var shade=0.55*Math.max(0,0.55-faceDiff);
    if(shade>0.01){
      ctx.fillStyle='rgba(8,7,16,'+shade.toFixed(3)+')';
      ctx.beginPath(); ctx.arc(0,0,DR+0.4,0,7); ctx.fill();
    }

    // raking sheen band — position q sweeps deterministically with rotation
    var q=Math.min(0.9,Math.max(0.1, 0.5+0.42*nF[0]));
    var sA=0.10+0.30*faceSpec+0.10*faceDiff;
    var sg=ctx.createLinearGradient(-gx*150,-gy*150,gx*150,gy*150);
    sg.addColorStop(0,'rgba(255,255,255,0)');
    sg.addColorStop(Math.max(0,q-0.16),'rgba(255,255,255,0)');
    sg.addColorStop(q,'rgba(255,255,255,'+sA.toFixed(3)+')');
    sg.addColorStop(Math.min(1,q+0.16),'rgba(255,255,255,0)');
    sg.addColorStop(1,'rgba(255,255,255,0)');
    ctx.fillStyle=sg;
    ctx.beginPath(); ctx.arc(0,0,DR+0.4,0,7); ctx.fill();

    // full-face specular flash when normal bisects light & view
    if(faceSpec>0.003){
      ctx.fillStyle='rgba(255,252,240,'+(0.5*faceSpec).toFixed(3)+')';
      ctx.beginPath(); ctx.arc(0,0,DR+0.4,0,7); ctx.fill();
    }

    // crisp junction between face and reeded edge
    ctx.strokeStyle=px(c,0.42); ctx.lineWidth=2.2;
    ctx.beginPath(); ctx.arc(0,0,DR-1.1,0,7); ctx.stroke();

    ctx.restore();
  }
  ctx.setTransform(1,0,0,1,0,0);
}

